import {t} from './i18n.js';
export function createOcrReview(root,textarea,{onPage=()=>{}}={}){
 let pages=[],active=0,url=null,dirty=false,mappings=[],zoom=1,destroyed=false;
 const select=document.createElement('select');select.id='ocr-review-page';select.setAttribute('aria-label',t('صفحة المراجعة'));
 const toolbar=document.createElement('div');toolbar.className='review-toolbar';const smaller=document.createElement('button'),larger=document.createElement('button');for(const b of [smaller,larger]){b.type='button';b.className='secondary';}smaller.textContent='−';larger.textContent='＋';smaller.setAttribute('aria-label',t('تصغير الصورة'));larger.setAttribute('aria-label',t('تكبير الصورة'));toolbar.append(select,smaller,larger);
 const viewport=document.createElement('div');viewport.className='review-image-scroll';viewport.tabIndex=0;viewport.setAttribute('aria-label',t('صورة الصفحة والكلمة المحددة'));const stage=document.createElement('div');stage.className='review-image-stage';const img=document.createElement('img');img.alt=t('صورة الصفحة الأصلية للمراجعة');const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),rect=document.createElementNS(svg.namespaceURI,'rect');svg.setAttribute('aria-hidden','true');rect.setAttribute('class','review-word-box');rect.hidden=true;svg.append(rect);stage.append(img,svg);viewport.append(stage);
 const weak=document.createElement('div');weak.className='review-weak-words';weak.setAttribute('aria-label',t('كلمات تحتاج تدقيقاً'));const hint=document.createElement('p');hint.className='hint';hint.textContent=t('اضغط كلمة بالصورة أو حددها بالنص لرؤية مكانها. الكلمات الملوّنة تحتاج تدقيقاً.');root.append(toolbar,viewport,hint,weak);
 function choosePage(index){active=Math.max(0,Math.min(index,pages.length-1));select.value=String(active);if(url)URL.revokeObjectURL(url);url=null;const page=pages[active];rect.style.display='none';if(!page){img.removeAttribute('src');return;}url=URL.createObjectURL(page.blob);img.src=url;svg.setAttribute('viewBox',`0 0 ${page.width} ${page.height}`);stage.style.width=zoom*100+'%';onPage(page);renderWeak();}
 function map(){mappings=[];if(dirty)return;let base=0;for(let p=0;p<pages.length;p++){const text=pages[p].ocr?.text||'';let offset=0;if(!pages[p].ocr?.edited)for(const word of pages[p].ocr?.words||[]){const start=text.indexOf(word.text,offset);if(start<0)continue;mappings.push({word,page:p,start:base+start,end:base+start+word.text.length});offset=start+word.text.length;}base+=text.length+2;}}
 function highlight(item,focus=false){if(!item||dirty){rect.style.display='none';return;}if(item.page!==active)choosePage(item.page);const b=item.word.bbox;if(!b)return;rect.style.display='block';rect.setAttribute('x',String(b.x0));rect.setAttribute('y',String(b.y0));rect.setAttribute('width',String(Math.max(1,b.x1-b.x0)));rect.setAttribute('height',String(Math.max(1,b.y1-b.y0)));rect.setAttribute('data-word',item.word.text);if(focus){textarea.focus({preventScroll:true});textarea.setSelectionRange(item.start,item.end);}const width=stage.getBoundingClientRect().width,page=pages[active],height=img.getBoundingClientRect().height;viewport.scrollTo({left:Math.max(0,b.x0/page.width*width-viewport.clientWidth/3),top:Math.max(0,b.y0/page.height*height-viewport.clientHeight/3),behavior:'auto'});}
 function renderWeak(){weak.replaceChildren();if(dirty){hint.textContent=t('النص معدّل: الربط بالصورة متوقف حتى إعادة الاستخراج، لحماية تصحيحاتك.');return;}hint.textContent=t('اضغط كلمة بالصورة أو حددها بالنص لرؤية مكانها. الكلمات الملوّنة تحتاج تدقيقاً.');for(const item of mappings.filter(m=>m.page===active&&m.word.confidence<70).slice(0,80)){const b=document.createElement('button');b.type='button';b.className='review-weak-word';b.dataset.userContent='';b.textContent=item.word.text;b.onclick=()=>highlight(item,true);weak.append(b);}}
 const selected=()=>highlight(mappings.find(m=>textarea.selectionStart<m.end&&textarea.selectionEnd>=m.start));
 const edited=()=>{dirty=true;rect.style.display='none';renderWeak();};textarea.addEventListener('select',selected);textarea.addEventListener('keyup',selected);textarea.addEventListener('click',selected);textarea.addEventListener('input',edited);
 viewport.onclick=event=>{if(dirty||!pages[active])return;const r=img.getBoundingClientRect(),page=pages[active],x=(event.clientX-r.left)*page.width/r.width,y=(event.clientY-r.top)*page.height/r.height;const item=mappings.find(m=>m.page===active&&x>=m.word.bbox.x0&&x<=m.word.bbox.x1&&y>=m.word.bbox.y0&&y<=m.word.bbox.y1);if(item)highlight(item,true);};
 select.onchange=()=>{zoom=1;choosePage(Number(select.value));};smaller.onclick=()=>{zoom=Math.max(1,zoom-.5);stage.style.width=zoom*100+'%';};larger.onclick=()=>{zoom=Math.min(4,zoom+.5);stage.style.width=zoom*100+'%';};
 return{
  update(next,{force=false}={}){if(destroyed)return false;if(dirty&&!force)return false;pages=next;dirty=false;textarea.value=pages.map(p=>p.ocr?.text||'').join('\n\n');select.replaceChildren(...pages.map((p,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=t('صفحة {n}',{n:i+1});return o;}));map();choosePage(active);return true;},
  get dirty(){return dirty;},get activePage(){return pages[active];},
  destroy(){destroyed=true;if(url)URL.revokeObjectURL(url);textarea.removeEventListener('select',selected);textarea.removeEventListener('keyup',selected);textarea.removeEventListener('click',selected);textarea.removeEventListener('input',edited);root.replaceChildren();}
 };
}
